import {loadImage} from './paper.js';
import {drawWrapped} from './text-layout.js';
const origin='https://capimimo-atelier-lembrancas.marketeam12.chatgpt.site';
export function receiptUrl(data){const payload={};for(const key of ['recipient','message','color','occasion','format','character','person','texture','pattern','eventDate','eventPlace','wedding','model'])payload[key]=data[key];const bytes=new TextEncoder().encode(JSON.stringify(payload));let binary='';bytes.forEach(b=>binary+=String.fromCharCode(b));return origin+'/#receber='+btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
export function readReceipt(){if(!location.hash.startsWith('#receber='))return null;try{const raw=location.hash.slice(9);if(raw.length>5000)return null;const binary=atob(raw.replace(/-/g,'+').replace(/_/g,'/'));const data=JSON.parse(new TextDecoder().decode(Uint8Array.from(binary,c=>c.charCodeAt(0))));const clean={};for(const [key,max] of [['recipient',34],['message',180],['eventDate',10],['eventPlace',60],['model',40]])clean[key]=String(data[key]||'').slice(0,max);if(['livro','cartao','convite'].includes(data.format))clean.format=data.format;if(['amizade','casamento','natal','maes','pais','aniversario','pascoa','namorados'].includes(data.occasion))clean.occasion=data.occasion;if(['capy','people'].includes(data.character))clean.character=data.character;if(Number.isInteger(data.person)&&data.person>=0&&data.person<12)clean.person=data.person;if(/^#[0-9A-Fa-f]{6}$/.test(data.color))clean.color=data.color;if(['linho','algodao','kraft'].includes(data.texture))clean.texture=data.texture;if(/^(natal|aniversario|casamento)-[0-3]$/.test(data.pattern))clean.pattern=data.pattern;clean.wedding=data.wedding==='invite'?'invite':'gift';return clean;}catch{return null;}}
export function createQRControls(getData,onChange){const details=document.createElement('details');details.className='options-panel qr-panel';details.innerHTML='<summary>Cartão de entrega com QR Code</summary><div class="qr-style-options"><button data-qr-style="carta" aria-pressed="true">Carta</button><button data-qr-style="retrato" aria-pressed="false">Retrato</button><button data-qr-style="selo" aria-pressed="false">Selo</button></div><canvas class="qr-card-preview" width="720" height="960" role="img" aria-label="Prévia do cartão com QR Code"></canvas><button class="download-qr" type="button">Baixar cartão com QR</button><p class="qr-explanation">Prévia privada. O QR leva o texto e as escolhas deste mimo; a foto fica apenas neste aparelho. O acesso segue a permissão desta página.</p>';
 document.querySelector('.customizer-bottom').before(details);const canvas=details.querySelector('canvas'),ctx=canvas.getContext('2d');let version=0;
 async function render(){if(!details.open)return;const current=++version,data=getData();const [pattern,art,photo]=await Promise.all([loadImage('assets/pattern-'+data.pattern+'.webp').catch(()=>null),loadImage('assets/'+data.theme.sheet+'.webp'),data.photo?loadImage(data.photo).catch(()=>null):null]);if(version!==current)return;ctx.fillStyle=data.color;ctx.fillRect(0,0,720,960);if(pattern)ctx.drawImage(pattern,0,0,720,960);ctx.fillStyle='#fffaf2';ctx.fillRect(28,28,664,904);ctx.fillStyle='#4b2c28';ctx.textAlign='center';ctx.font='38px "Fraunces",Georgia';drawWrapped(ctx,data.recipient?'Para '+data.recipient:'Um mimo para você',360,93,600,43,2);const cell=art.width/4;if(data.qrStyle==='retrato'){ctx.fillStyle='#d9e5ec';ctx.beginPath();ctx.arc(360,244,99,0,Math.PI*2);ctx.fill();}if(data.qrStyle==='retrato'&&photo){const scale=Math.min(270/photo.width,170/photo.height);ctx.drawImage(photo,360-photo.width*scale/2,160,photo.width*scale,photo.height*scale);}else ctx.drawImage(art,(data.theme.col||0)*cell,data.theme.row*cell,cell,cell,270,160,180,180);
  if(typeof window.qrcode==='function'){const qr=window.qrcode(0,'M');qr.addData(receiptUrl(data));qr.make();const n=qr.getModuleCount(),unit=Math.floor(400/(n+8)),box=unit*(n+8),left=Math.floor((720-box)/2),top=350;ctx.fillStyle='#ffffff';ctx.fillRect(150,340,420,420);ctx.fillStyle='#000000';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))ctx.fillRect(left+(x+4)*unit,top+(y+4)*unit,unit,unit);canvas.dataset.qrBounds=JSON.stringify({left,top,width:box,height:box});canvas.dataset.qrUrl=receiptUrl(data);canvas.dataset.qrModules=String(n);}
  ctx.fillStyle='#4b2c28';ctx.font='28px "DM Sans",sans-serif';ctx.fillText('Aponte a câmera para abrir.',360,793);ctx.font='22px "DM Sans",sans-serif';ctx.fillText('Uma lembrança feita para você.',360,842);if(data.qrStyle==='selo'){ctx.strokeStyle=data.color;ctx.lineWidth=3;ctx.strokeRect(43,43,634,874);}details.querySelectorAll('[data-qr-style]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.qrStyle===(data.qrStyle||'carta'))));}
 details.addEventListener('toggle',render);details.querySelectorAll('[data-qr-style]').forEach(b=>b.addEventListener('click',()=>onChange({qrStyle:b.dataset.qrStyle})));details.querySelector('.download-qr').addEventListener('click',async()=>{await render();const a=document.createElement('a');a.download='meu-mimo-cartao-qr.png';a.href=canvas.toDataURL('image/png');a.click();});return {render};}
